{
  "title": "Discussion about living abroad, job hunting and language requirements",
  "topics": [
    {
      "id": "expat-community",
      "title": "Expats living in Slovakia and Austria",
      "claims": [
        {
          "text": "Known expatriates include @AndriiRaccoon in Austria and walternet134 in Poland",
          "evidence": [3]
        },
        {
          "text": "P3 has at least two acquaintances in Austria",
          "evidence": [12]
        },
        {
          "text": "One acquaintance arrived recently, another has been living there for several years",
          "evidence": [13]
        },
        {
          "text": "P3 has been in Austria since 17.11.2025",
          "evidence": [49]
        },
        {
          "text": "P3 mentions being in Austria since around 03.09.2025",
          "evidence": [54]
        },
        {
          "text": "P3 lives with a boyfriend who has lived in Austria for more than 10 years",
          "evidence": [60]
        }
      ]
    },
    {
      "id": "job-search-language",
      "title": "Job search strategies and language requirements",
      "claims": [
        {
          "text": "Search for jobs on LinkedIn",
          "evidence": [18]
        },
        {
          "text": "The highest conversion step is from vacancy posting to interview",
          "evidence": [20]
        },
        {
          "text": "P3 sent roughly 100 applications and received only 3 interview invitations",
          "evidence": [21]
        },
        {
          "text": "About 95% of vacancies explicitly require the local language",
          "evidence": [26]
        },
        {
          "text": "Many candidates are filtered out early because they do not meet language requirements",
          "evidence": [27]
        },
        {
          "text": "There are cases where candidates with limited language skills are still hired",
          "evidence": [29]
        },
        {
          "text": "Higher education rarely influences hiring decisions",
          "evidence": [32]
        },
        {
          "text": "Typical language requirement is B2 level, sometimes B1; candidates often list B2 without having a certificate",
          "evidence": [46]
        },
        {
          "text": "P3 started learning the local language because of discomfort navigating the city and fear of being seen as a migrant",
          "evidence": [47]
        }
      ]
    },
    {
      "id": "salary-experience",
      "title": "Salary expectations and experience",
      "claims": [
        {
          "text": "P3 has around 3 years of professional experience",
          "evidence": [23]
        },
        {
          "text": "P3's salary was higher than typical, but they accepted the minimum offered for the role",
          "evidence": [37]
        },
        {
          "text": "P3 needed a job by 04.03 and started working on 02.03",
          "evidence": [39, 41]
        },
        {
          "text": "A candidate without commercial experience was called for a mid‑level interview, likely due to a master’s degree",
          "evidence": [28]
        }
      ]
    },
    {
      "id": "tech-engagement",
      "title": "Community engagement and tech events",
      "claims": [
        {
          "text": "P3 suggests attending the Warsaw tech event https://wawtech.io/summer",
          "evidence": [59]
        },
        {
          "text": "P1 wants to join Discord channels to practice English conversation",
          "evidence": [56, 57]
        }
      ]
    }
  ],
  "decisions": [
    {
      "text": "Use LinkedIn as the primary platform for job searching",
      "evidence": [18]
    }
  ],
  "openQuestions": [
    {
      "text": "Who currently lives in Bratislava or elsewhere in Slovakia, and who has moved abroad?",
      "evidence": [1]
    }
  ]
}
